<?php session_start(); $logged=!empty($_SESSION['pro_admin']); ?><!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fast Food • Admin Pro</title><style>
:root{--bg:#f6f7fb;--card:#fff;--ink:#101828;--muted:#667085;--brand:#ff4d00;--line:#e4e7ec;--dark:#101828;--ok:#12b76a;--bad:#f04438;--shadow:0 18px 50px #10182812}*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,Arial;background:var(--bg);color:var(--ink)}button,input,textarea,select{font:inherit}.login{min-height:100vh;display:grid;place-items:center;padding:20px;background:radial-gradient(circle at 20% 10%,#ffe0d2,transparent 35%),radial-gradient(circle at 90% 90%,#ffe7c8,transparent 35%),var(--bg)}.box{background:var(--card);border:1px solid var(--line);border-radius:26px;padding:30px;box-shadow:var(--shadow)}.login .box{width:min(420px,100%)}.logo{font-size:34px}.field{margin:12px 0}.field label{display:block;font-weight:800;margin-bottom:6px}.field input,.field textarea,.field select{width:100%;padding:11px 12px;border:1px solid var(--line);border-radius:12px;background:#fff}.btn{border:0;border-radius:12px;padding:10px 14px;font-weight:800;cursor:pointer}.primary{background:linear-gradient(135deg,#ff4d00,#ff7a00);color:#fff}.ghost{background:#f2f4f7;color:#344054}.danger{background:#fee4e2;color:#b42318}.app{display:flex;min-height:100vh}.side{position:fixed;inset:0 auto 0 0;width:250px;background:#101828;color:#fff;padding:20px 14px}.brand{font-size:22px;font-weight:900;padding:10px 12px 22px}.nav button{width:100%;border:0;background:transparent;color:#cbd5e1;text-align:left;padding:12px;border-radius:12px;margin:3px 0;cursor:pointer}.nav button.active,.nav button:hover{background:#ffffff12;color:#fff}.main{margin-left:250px;width:calc(100% - 250px);padding:24px}.top{display:flex;justify-content:space-between;gap:15px;align-items:center;margin-bottom:20px}.top h1{margin:0}.live{display:inline-flex;align-items:center;gap:7px;color:var(--ok);font-weight:800}.dot{width:9px;height:9px;border-radius:50%;background:var(--ok);box-shadow:0 0 0 5px #12b76a18}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}.metric{font-size:28px;font-weight:900;margin-top:7px}.muted{color:var(--muted)}.tabs{display:none}.section{display:none}.section.active{display:block}.grid{display:grid;grid-template-columns:1.5fr 1fr;gap:16px;margin-top:16px}.tablewrap{overflow:auto}.table{width:100%;border-collapse:collapse;min-width:760px}.table th,.table td{padding:12px;border-bottom:1px solid var(--line);text-align:left}.badge{padding:6px 9px;border-radius:999px;font-size:12px;font-weight:900}.new{background:#fff1b8}.confirmed{background:#dbeafe}.preparing{background:#ede9fe}.delivering{background:#cffafe}.completed{background:#dcfce7}.cancelled{background:#fee2e2}.toolbar{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:14px}.productgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.pitem{border:1px solid var(--line);border-radius:18px;padding:15px}.pitem img{width:100%;height:150px;object-fit:contain;background:#f8fafc;border-radius:12px}.toast{position:fixed;right:18px;bottom:18px;background:#101828;color:#fff;padding:12px 15px;border-radius:12px;display:none;z-index:10}@media(max-width:1000px){.cards{grid-template-columns:repeat(2,1fr)}.grid,.productgrid{grid-template-columns:1fr}}@media(max-width:700px){.side{width:68px}.brand{font-size:0}.brand:after{content:'🍔';font-size:25px}.nav button{font-size:0;text-align:center}.nav button:first-letter{font-size:20px}.main{margin-left:68px;width:calc(100% - 68px);padding:13px}.cards{grid-template-columns:1fr 1fr}.top{align-items:flex-start}.top h1{font-size:21px}}
</style></head><body><?php if(!$logged): ?><div class="login"><div class="box"><div class="logo">🍔</div><h1>Fast Food Admin Pro</h1><p class="muted">Jonli buyurtmalar, mahsulotlar, kuryerlar va mijozlar.</p><form id="login"><div class="field"><label>Login</label><input name="username" required autocomplete="username"></div><div class="field"><label>Parol</label><input name="password" type="password" required autocomplete="current-password"></div><button class="btn primary" style="width:100%">Kirish</button></form><p id="err" class="muted"></p></div></div><script>login.onsubmit=async e=>{e.preventDefault();let r=await fetch('admin_pro_api.php?action=login',{method:'POST',body:new FormData(e.target)}),d=await r.json();d.ok?location.reload():err.textContent=d.message||'Xato'}</script><?php else: ?><div class="app"><aside class="side"><div class="brand">🍔 Fast Food</div><nav class="nav"><button class="active" data-s="home">📊 Boshqaruv</button><button data-s="orders">🛵 Buyurtmalar</button><button data-s="products">🍔 Mahsulotlar</button><button data-s="couriers">🛵 Kuryerlar</button><button data-s="customers">👥 Mijozlar</button><button data-s="settings">⚙️ Sozlamalar</button></nav><button id="logout" class="btn danger" style="width:100%;margin-top:20px">Chiqish</button></aside><main class="main"><div class="top"><div><h1 id="title">Boshqaruv markazi</h1><span class="live"><i class="dot"></i> ONLINE • server bilan ulangan</span></div><a href="index.php" class="btn ghost">Sayt ↗</a></div>
<section id="home" class="section active"><div class="cards"><div class="box">📦 Buyurtmalar<div id="morders" class="metric">0</div></div><div class="box">🆕 Yangi<div id="mnew" class="metric">0</div></div><div class="box">📅 Bugun<div id="mtoday" class="metric">0</div></div><div class="box">💰 Tushum<div id="mrev" class="metric">0</div></div><div class="box">🛵 Kuryer online<div id="mcourier" class="metric">0</div></div></div><div class="grid"><div class="box"><h3>Jonli buyurtmalar</h3><div id="liveOrders" class="tablewrap"></div></div><div class="box"><h3>Do‘kon</h3><div id="store" class="muted">Yuklanmoqda...</div></div></div></section>
<section id="orders" class="section"><div class="box"><div class="toolbar"><button class="btn ghost" onclick="loadOrders()">↻ Yangilash</button><select id="filter" onchange="loadOrders()"><option value="">Barchasi</option><option value="new">Yangi</option><option value="confirmed">Tasdiqlangan</option><option value="preparing">Tayyorlanmoqda</option><option value="delivering">Yetkazilmoqda</option><option value="completed">Yakunlangan</option><option value="cancelled">Bekor</option></select></div><div id="ordersTable" class="tablewrap"></div></div></section>
<section id="products" class="section"><div class="box"><div class="toolbar"><button class="btn primary" onclick="editProduct()">＋ Mahsulot qo‘shish</button><button class="btn ghost" onclick="loadProducts()">↻ Yangilash</button></div><div id="productGrid" class="productgrid"></div></div></section>
<section id="couriers" class="section"><div class="box"><div class="toolbar"><button class="btn primary" onclick="editCourier()">＋ Kuryer qo‘shish</button><button class="btn ghost" onclick="loadCouriers()">↻ Yangilash</button></div><div id="courierGrid" class="productgrid"></div></div></section>
<section id="customers" class="section"><div class="box"><h2>Mijozlar</h2><div id="customerTable" class="tablewrap"></div></div></section>
<section id="settings" class="section"><div class="box"><h2>Do‘kon sozlamalari</h2><form id="settingsForm"><div class="field"><label>Do‘kon nomi</label><input name="store_name"></div><div class="field"><label>Telefon</label><input name="phone"></div><div class="field"><label>Manzil</label><input name="address"></div><div class="field"><label>Dastavka</label><textarea name="delivery_note"></textarea></div><div class="field"><label>Dastavka narxi</label><input name="delivery_fee" type="number"></div><button class="btn primary">Saqlash</button></form></div></section></main></div><div id="toast" class="toast"></div>
<script>
const $=s=>document.querySelector(s),api=(a,o={})=>fetch('admin_pro_api.php?action='+a,o).then(r=>r.json()),toast=x=>{let t=$('#toast');t.textContent=x;t.style.display='block';setTimeout(()=>t.style.display='none',1800)},esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
async function home(){let d=await api('summary');if(!d.ok)return;let x=d.data;$('#morders').textContent=x.orders;$('#mnew').textContent=x.new;$('#mtoday').textContent=x.today;$('#mrev').textContent=Number(x.revenue).toLocaleString('uz-UZ')+' so‘m';$('#mcourier').textContent=x.online_couriers;let s=await api('settings');$('#store').innerHTML='<b>'+esc(s.data.store_name)+'</b><br>📞 '+esc(s.data.phone)+'<br>📍 '+esc(s.data.address)+'<br>🚚 '+esc(s.data.delivery_note);let o=await api('orders&status=new');$('#liveOrders').innerHTML=o.data.length?o.data.slice(0,8).map(x=>`<div style="padding:11px;border-bottom:1px solid #eee"><b>#${x.id} ${esc(x.customer_name)}</b> · ${esc(x.phone)}<br><span class="muted">${esc(x.address||'')}</span> · <b>${Number(x.amount).toLocaleString('uz-UZ')} so‘m</b></div>`).join(''):'<div class="muted">Yangi buyurtma yo‘q</div>'}
async function loadOrders(){let f=$('#filter').value,d=await api('orders&status='+encodeURIComponent(f));let rows=d.data||[];$('#ordersTable').innerHTML='<table class="table"><thead><tr><th>#</th><th>Mijoz</th><th>Aloqa</th><th>Manzil</th><th>Summa</th><th>Kuryer</th><th>Status</th></tr></thead><tbody>'+rows.map(x=>`<tr><td>#${x.id}<br><small>${new Date(x.created_at).toLocaleString('uz-UZ')}</small></td><td><b>${esc(x.customer_name)}</b><br>${esc(x.note||'')}</td><td>${esc(x.phone)}</td><td>${esc(x.address||'')}</td><td><b>${Number(x.amount).toLocaleString('uz-UZ')} so‘m</b></td><td>${esc(x.courier_name||'—')}<br>${esc(x.courier_phone||'')}</td><td><select class="badge ${x.status}" onchange="changeStatus(${x.id},this.value)">${['new','confirmed','preparing','delivering','completed','cancelled'].map(s=>`<option value="${s}" ${s===x.status?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')+'</tbody></table>'}
async function changeStatus(id,status){let f=new FormData();f.append('id',id);f.append('status',status);let d=await api('status',{method:'POST',body:f});toast(d.ok?'Status saqlandi':'Xato');home()}
async function loadProducts(){let d=await api('products');$('#productGrid').innerHTML=(d.data||[]).map(p=>`<div class="pitem"><img src="images/${esc(p.p_image)}" onerror="this.style.display='none'"><h3>${esc(p.p_title)}</h3><p class="muted">${esc(p.p_desc)}</p><b>${Number(p.p_prize).toLocaleString('uz-UZ')} so‘m</b><p><span class="badge ${p.status==='show'?'completed':'cancelled'}">${p.status}</span></p><button class="btn ghost" onclick='editProduct(${JSON.stringify(p)})'>Tahrirlash</button> <button class="btn danger" onclick="delProduct(${p.id})">O‘chirish</button></div>`).join('')}
async function editProduct(p={}){let title=prompt('Mahsulot nomi',p.p_title||'');if(title===null)return;let price=prompt('Narxi',p.p_prize||0);if(price===null)return;let f=new FormData();[['id',p.id||0],['p_title',title],['p_subtitle',p.p_subtitle||''],['p_desc',p.p_desc||''],['p_prize',price],['cat_id',p.cat_id||'cat-20001'],['scat_id',p.scat_id||'scat-30001'],['p_image',p.p_image||'dish-1.png'],['status',p.status||'show']].forEach(x=>f.append(x[0],x[1]));let d=await api('product_save',{method:'POST',body:f});toast(d.ok?'Mahsulot saqlandi':'Xato');loadProducts()}
async function delProduct(id){if(!confirm('Mahsulot o‘chirilsinmi?'))return;let f=new FormData();f.append('id',id);let d=await api('product_delete',{method:'POST',body:f});toast(d.ok?'O‘chirildi':'Xato');loadProducts()}
async function loadCouriers(){let d=await api('couriers');$('#courierGrid').innerHTML=(d.data||[]).map(c=>`<div class="pitem"><h3>${esc(c.name)} ${c.online?'🟢':'⚪'}</h3><p>${esc(c.phone)}</p><p class="muted">${c.online?'Online':'Offline'}</p><button class="btn ghost" onclick='editCourier(${JSON.stringify(c)})'>Tahrirlash</button> <button class="btn danger" onclick="delCourier(${c.id})">O‘chirish</button></div>`).join('')||'<div class="muted">Kuryer qo‘shilmagan</div>'}
async function editCourier(c={}){let name=prompt('Kuryer ismi',c.name||'');if(name===null)return;let phone=prompt('Telefon',c.phone||'+998');if(phone===null)return;let f=new FormData();f.append('id',c.id||0);f.append('name',name);f.append('phone',phone);let d=await api('courier_save',{method:'POST',body:f});toast(d.ok?'Kuryer saqlandi':'Xato');loadCouriers()}
async function delCourier(id){if(!confirm('Kuryer o‘chirilsinmi?'))return;let f=new FormData();f.append('id',id);await api('courier_delete',{method:'POST',body:f});loadCouriers()}
async function loadCustomers(){let d=await api('customers');$('#customerTable').innerHTML='<table class="table"><thead><tr><th>Mijoz</th><th>Telefon</th><th>Manzil</th><th>Buyurtma</th><th>Jami</th></tr></thead><tbody>'+(d.data||[]).map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.phone)}</td><td>${esc(x.address||'')}</td><td>${x.orders}</td><td>${Number(x.spent).toLocaleString('uz-UZ')} so‘m</td></tr>`).join('')+'</tbody></table>'}
async function settings(){let d=await api('settings');if(!d.ok)return;Object.entries(d.data).forEach(([k,v])=>{let e=$(`[name="${k}"]`);if(e)e.value=v})}$('#settingsForm').onsubmit=async e=>{e.preventDefault();let d=await api('settings',{method:'POST',body:new FormData(e.target)});toast(d.ok?'Saqlandi':'Xato')};$('#logout').onclick=async()=>{await api('logout');location.reload()};document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.section').forEach(x=>x.classList.remove('active'));let s=b.dataset.s;$('#'+s).classList.add('active');$('#title').textContent=b.textContent.trim();if(s==='orders')loadOrders();if(s==='products')loadProducts();if(s==='couriers')loadCouriers();if(s==='customers')loadCustomers();if(s==='settings')settings()});
home();settings();setInterval(home,5000);setInterval(()=>{if($('#orders').classList.contains('active'))loadOrders()},5000);setInterval(()=>{if($('#couriers').classList.contains('active'))loadCouriers()},10000);
</script><?php endif; ?></body></html>